// authChainRouter mounts the REAL production router over a live store and
// identity service — the black-box shape: every assertion in this file rides
// the same chain a production request rides (authMiddleware → requireRole →
// handler → viewerFor), never a synthetic principal injection.
func authChainRouter(t *testing.T, st *store.Store, ident *identity.Service) http.Handler {
	t.Helper()
	return New(Deps{
		AdminToken: adminToken,
		Store:      st,
		Identity:   ident,
		Pairing:    pairing.NewService(st, nil),
	})
}

// seedGrantedLibrary carves one library and one group granted exactly that
// library, with username as the group's sole member — the minimal live
// accounts deployment for a scoped principal (the resolve-test seeding
// pattern). Returns the granted library id and the SEED library (a second,
// never-granted library the scoped principal must not see).
func seedGrantedLibrary(t *testing.T, ident *identity.Service, st *store.Store, username string) (granted, hidden int64) {
	t.Helper()
	ctx := context.Background()
	granted = seedLibrary(t, st, "/media/granted-"+username)
	hidden = seedLibrary(t, st, "/media/hidden-"+username)
	if _, err := ident.CreateGroup(ctx, "Scope"); err != nil {
		t.Fatalf("CreateGroup: %v", err)
	}
	if err := ident.AddCollection(ctx, "Scope", granted, 0); err != nil {
		t.Fatalf("AddCollection: %v", err)
	}
	if err := ident.AddUser(ctx, "Scope", username); err != nil {
		t.Fatalf("AddUser: %v", err)
	}
	return granted, hidden
}

// listedLibraryIDs decodes a GET /api/v1/libraries response into the id set.
func listedLibraryIDs(t *testing.T, resp *http.Response) map[int64]bool {
	t.Helper()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("libraries status = %d, want 200", resp.StatusCode)
	}
	var lr librariesResponse
	if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
		t.Fatalf("decode librariesResponse: %v", err)
	}
	ids := map[int64]bool{}
	for _, l := range lr.Items {
		ids[l.ID] = true
	}
	return ids
}

func TestAuthChainSessions(t *testing.T) {
	st := openAPIStore(t)
	ident := identity.NewService(st, nil)
	ctx := context.Background()
	if _, err := ident.Create(ctx, "alia", "pw"); err != nil {
		t.Fatalf("identity.Create: %v", err)
	}
	granted, hidden := seedGrantedLibrary(t, ident, st, "alia")
	// The mint rides the REAL password path (MintSession verifies argon2id);
	// the login endpoint itself is 7.2 and deliberately not exercised here.
	sess, err := ident.MintSession(ctx, "alia", "pw")
	if err != nil {
		t.Fatalf("MintSession: %v", err)
	}
	h := authChainRouter(t, st, ident)

	t.Run("session_reaches_browse_as_its_user", func(t *testing.T) {
		ids := listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", sess.Token))
		if !ids[granted] || ids[hidden] || len(ids) != 1 {
			t.Fatalf("session library list = %v, want exactly the grant {%d}", ids, granted)
		}
	})

	t.Run("admin_role_session_reaches_admin_route", func(t *testing.T) {
		// Role projection end-to-end (D11): the SAME bearer token, after the
		// user's row flips to admin, passes requireRole(RoleAdmin) on the
		// admin group — no new Role constant, the projection happens at the
		// middleware on the next verify.
		if err := ident.SetRole(ctx, "alia", "admin"); err != nil {
			t.Fatalf("SetRole: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", sess.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("admin-role session on admin route = %d, want 200", resp.StatusCode)
		}
	})

	t.Run("disabled_user_session_fails_closed", func(t *testing.T) {
		// The disabled flag is re-checked at every verify — the same live
		// token 401s uniformly with a miss (D3 fail-closed).
		if err := ident.SetDisabled(ctx, "alia", true); err != nil {
			t.Fatalf("SetDisabled: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", sess.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("disabled user's session = %d, want 401", resp.StatusCode)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unauthenticated" {
			t.Fatalf("error code = %q, want unauthenticated (uniform with a miss)", eb.Error.Code)
		}
	})

	t.Run("garbage_bearer_401", func(t *testing.T) {
		// Not the admin token, no device row, no session row: the uniform 401.
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", "definitely-not-a-credential")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("garbage bearer = %d, want 401", resp.StatusCode)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unauthenticated" {
			t.Fatalf("error code = %q, want unauthenticated", eb.Error.Code)
		}
	})
}

func TestAuthChainDevices(t *testing.T) {
	st := openAPIStore(t)
	ident := identity.NewService(st, nil)
	devices := pairing.NewService(st, nil)
	ctx := context.Background()
	u, err := ident.Create(ctx, "vera", "pw")
	if err != nil {
		t.Fatalf("identity.Create: %v", err)
	}
	granted, hidden := seedGrantedLibrary(t, ident, st, "vera")

	// Mint TWO real device credentials through the real pairing flow, then
	// bind exactly one to vera. Binding rows are written by the admin bind
	// endpoint (9.3, not yet built) — the test seeds the credentials row's
	// user_id directly, which is the exact row state the middleware reads.
	mintDevice := func(t *testing.T) string {
		t.Helper()
		req, err := devices.CreateRequest(ctx, "10.0.0.1")
		if err != nil {
			t.Fatalf("CreateRequest: %v", err)
		}
		if _, err := devices.Approve(ctx, req.ID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		out, err := devices.Wait(ctx, req.ID)
		if err != nil || out.Token == "" {
			t.Fatalf("Wait: outcome=%+v err=%v (want the raw device token once)", out, err)
		}
		return out.Token
	}
	boundToken := mintDevice(t)
	if _, err := st.DB().ExecContext(ctx,
		`UPDATE credentials SET user_id = ? WHERE token_hash = ?`,
		u.ID, hashBearerToken(boundToken)); err != nil {
		t.Fatalf("bind device credential: %v", err)
	}
	unboundToken := mintDevice(t)
	h := authChainRouter(t, st, ident)

	t.Run("bound_device_rides_user_scope", func(t *testing.T) {
		ids := listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", boundToken))
		if !ids[granted] || ids[hidden] || len(ids) != 1 {
			t.Fatalf("bound device library list = %v, want exactly the bound user's grant {%d}", ids, granted)
		}
	})

	t.Run("unbound_device_sees_all", func(t *testing.T) {
		// Today's posture, unchanged: a device credential with user_id NULL
		// keeps the explicit see-all (LegacyDevice), even under a LIVE
		// accounts deployment.
		ids := listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", unboundToken))
		if !ids[granted] || !ids[hidden] {
			t.Fatalf("unbound device library list = %v, want see-all (both {%d, %d})", ids, granted, hidden)
		}
	})

	t.Run("env_admin_unchanged", func(t *testing.T) {
		ids := listedLibraryIDs(t, doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", adminToken))
		if !ids[granted] || !ids[hidden] {
			t.Fatalf("env admin library list = %v, want see-all", ids)
		}
	})
}
